-- ROLLBACK for 2026-06-18_fix_view_xschema_contacts_ss_target.sql
-- Restores the ORIGINAL (broken) definition captured verbatim from
-- `SHOW CREATE VIEW actorsbusinessoffice.contacts_ss_target` on 2026-06-18:
-- every table reference re-qualified with `new_development.`.
--
-- WARNING: This re-introduces the cross-schema bug -- in PROD the Targeted tab
--          will again read the DEV database and return no rows. Use only to
--          revert if the forward migration causes an unexpected regression.
--
-- Run via mysql CLI ONLY (not phpMyAdmin), connected to the target schema.

CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`kingk436`@`%` SQL SECURITY DEFINER VIEW `contacts_ss_target` AS select `new_development`.`d`.`contactID` AS `contactid`,concat('<input type="checkbox" class="form-check-input" id="C',`new_development`.`d`.`contactID`,'" name="batchlist"  value="',`new_development`.`d`.`contactID`,'">') AS `contactcheck`,concat('<img src="/mediaroot/users/',`new_development`.`d`.`userID`,'/contacts/',`new_development`.`d`.`contactID`,'/avatar.jpg?ver=',`new_development`.`d`.`contactID`,'" class="mr-3  rounded-circle gambar img-responsive img-thumbnail" style="height:20px;" alt="profile-image" >') AS `avatar`,concat('<a href="/app/contact/?contactid=',`new_development`.`d`.`contactID`,'" >',`new_development`.`d`.`contactFullName`,'</a>') AS `hlink`,`new_development`.`d`.`contactFullName` AS `col1`,(select group_concat(concat('<span class=\'badge badge-blue\'>',`new_development`.`contactitems`.`valueText`,'</span>') separator ' ') from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Tag') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active')) limit 1) AS `col2`,concat(coalesce(substring_index((select group_concat(concat('<span class=\'badge badge-blue\'>',`new_development`.`contactitems`.`valueText`,'</span>') order by `new_development`.`contactitems`.`valueText` ASC separator '&nbsp; ') from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Tag') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active'))),'&nbsp;',2),''),convert(convert(coalesce((case when (((select count(0) from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Tag') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active'))) - 2) > 0) then concat(' +',((select count(0) from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Tag') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active'))) - 2)) else NULL end),'') using utf8mb3) using utf8mb4)) AS `col2b`,(select `new_development`.`contactitems`.`valueText` from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Phone') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active')) order by `new_development`.`contactitems`.`primary_YN` desc limit 1) AS `col3`,(select `new_development`.`contactitems`.`valueText` from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`valueCategory` = 'Email') and (`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`itemStatus` = 'Active')) order by `new_development`.`contactitems`.`primary_YN` desc limit 1) AS `col4`,(select `new_development`.`contactitems`.`valueCompany` from `new_development`.`contactitems` where ((`new_development`.`contactitems`.`contactID` = `new_development`.`d`.`contactID`) and (`new_development`.`contactitems`.`valueCategory` = 'Company') and (`new_development`.`contactitems`.`itemStatus` = 'active')) order by `new_development`.`contactitems`.`primary_YN` desc limit 1) AS `col5`,`new_development`.`d`.`userID` AS `userid` from `new_development`.`contactdetails` `d` where ((`new_development`.`d`.`contactStatus` = 'Active') and `new_development`.`d`.`contactID` in (select `new_development`.`fusystemusers`.`contactID` from `new_development`.`fusystemusers` where (`new_development`.`fusystemusers`.`systemID` in (5,6))));
